theorem skew3_mul_skew3 (a b c p q r : K) :
    skew3 a b c * skew3 p q r =
      !![-a * p - b * q, -b * r, a * r;
         -c * q, -a * p - c * r, -a * q;
         c * p, -b * p, -b * q - c * r]

